'use strict';
const STARTERS=window.STARTERS||[];
function productName(id){return SETS.find(s=>s.id===id)?.name||STARTERS.find(s=>s.id===id)?.name||id;}
function cardOrigins(c){return `<details class="card-origins"><summary>Dónde conseguirla · ${(c.obtainable||[c]).map(p=>esc(p.set)).join(' / ')}</summary><ul>${(c.obtainable||[{set:c.set,code:c.code,rarity:c.rarity}]).map(p=>`<li>${esc(productName(p.set))} <span>${esc(p.code)} · ${esc(names[p.rarity]||p.rarity)}</span></li>`).join('')}${(state.economy?.customPacks||[]).filter(p=>p.entries.some(e=>e.id===String(c.id))).map(p=>`<li>Sobre especial · ${esc(p.name)}</li>`).join('')}${state.economy?.offers.some(o=>o.id===String(c.id)&&o.stock>0)?'<li>Disponible en la tienda</li>':''}</ul></details>`;}

function filteredPrint(c,set){const p=c.obtainable?.find(p=>p.set===set);return p?{...c,code:p.code,rarity:p.rarity}:c;}
function renderStarters(){
 $('#starterProducts').innerHTML=STARTERS.map(s=>{const hero=cards.find(c=>c.name_en===s.hero);return `<article class="starter-product ${s.id.toLowerCase()}"><img src="${esc(image(hero))}" alt="${esc(hero.name_en)}"><div><span class="eyebrow">${esc(s.edition)} · ${s.id}</span><h2>${esc(s.name)}</h2><p>50 cartas fijas · 1 ultra rara · 2 súper raras · 47 comunes</p><p>Sumá el contenido completo a tu colección y usalo para armar tus mazos.</p><button class="primary" data-get-starter="${s.id}">Comprar mazo · 500 monedas</button><button data-preview-starter="${s.id}">Ver las 50 cartas</button></div></article>`;}).join('');
 $('#starterContent').hidden=true;
}
function renderStarterContent(id){const s=STARTERS.find(s=>s.id===id);if(!s)return;$('#starterContent').hidden=false;$('#starterContent').dataset.selected=id;$('#starterContent').innerHTML=`<div class="section-heading"><h2>Contenido · ${esc(s.name)}</h2><button data-close-starter>Ocultar contenido</button><span>1 copia de cada carta</span></div><p class="micro">Rarezas y códigos de esta edición. El contador muestra las copias que ya tenés en total.</p><div class="cards">${s.entries.map(e=>tile({...byId.get(String(e.id)),code:e.code,rarity:e.rarity})).join('')}</div><p><a class="source-link" href="${esc(s.source)}" target="_blank" rel="noopener">Consultar lista de esta edición ↗</a></p>`;}
function grantStarter(id,createDeck=false){const s=STARTERS.find(s=>s.id===id);if(!s)throw Error('Mazo de inicio no válido');if(state.coins<500)throw Error('Necesitás 500 monedas para comprar este mazo.');if(createDeck&&state.decks.length>=200)throw Error('Ya tenés 200 mazos. Podés agregar solo las cartas.');for(const e of s.entries)if((state.owned[e.id]||0)+e.quantity>1e7)throw Error('Se alcanzó el límite de copias.');state.coins-=500;for(const e of s.entries)state.owned[e.id]=(state.owned[e.id]||0)+e.quantity;if(createDeck){const d={id:crypto.randomUUID(),name:s.name,cards:Object.fromEntries(s.entries.map(e=>[String(e.id),e.quantity]))};state.decks.push(d);currentDeck=d.id;}save();return s;}
function confirmStarter(id){const s=STARTERS.find(s=>s.id===id);if(!s)return;modal(`<h2>${esc(s.name)}</h2><p>El mazo cuesta 500 monedas. Tu saldo: ${state.coins.toLocaleString('es-AR')} monedas. Vas a agregar sus 50 cartas a tu colección. Las cartas que ya tengas recibirán una copia más.</p><label><input id="starterSaveDeck" type="checkbox"> Guardarlo también en Mis mazos, listo para editar</label><p class="micro">Podés agregar este producto más de una vez. No consume cartas de las cajas.</p><button id="confirmStarter" class="primary" ${state.coins<500?'disabled':''}>Comprar · 500 monedas</button>`);$('#confirmStarter').onclick=()=>{const button=$('#confirmStarter');button.disabled=true;try{grantStarter(id,$('#starterSaveDeck').checked);$('#modal').close();renderStarters();toast('50 cartas agregadas a tu colección');}catch(e){button.disabled=false;toast(e.message);}};}
$('#iniciales').addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-close-starter'))$('#starterContent').hidden=true;if(button.dataset.getStarter)confirmStarter(button.dataset.getStarter);if(button.dataset.previewStarter){renderStarterContent(button.dataset.previewStarter);$('#starterContent').scrollIntoView({behavior:'smooth',block:'start'});}});
$('#setFilter').insertAdjacentHTML('beforeend',STARTERS.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join(''));
